// Des: Command feed: stored chat messages to scra JSONL records
// Flo: only chats named in feed_chat_list (opt-in) > new messages since the last export per chat > one record each > --live writes one .jsonl atomically into scra's social-in folder, then remembers the last id; dry-run only counts
// I/O: Ctx + config feed_* (caller) > file <feed>/za-<ms>.jsonl; stdout counts; exit 0, 3 when nothing to do; never opens the browser, never reads Zalo
// ===================================================================
const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const file = @import("st-stor-file.zig"); const data = @import("st-stat-data.zig"); const confz = @import("cf-conf-load.zig");
const CF = .{ .kind = "zalo", .role = "private", .metk = "feed_last_", .base = "https://chat.zalo.me/c/", .secs = 100_000_000_000 };
pub const Reco = struct { kind: []const u8, id: []const u8, url: []const u8, text: []const u8, src: []const u8, auth: []const u8, role: []const u8, posted: i64 };
pub const Mark = struct { key: []const u8, id: i64 };
pub const Built = struct { body: []const u8, cntz: u32, skpz: u32, marks: []const Mark };
pub fn hexOf(aren: std.mem.Allocator, text: []const u8) ![]u8 { return std.fmt.allocPrint(aren, "{x:0>16}", .{std.hash.Wyhash.hash(0, text)}); }
fn cutUtf8(text: []const u8, maxz: usize) []const u8 { if (text.len <= maxz) return text; var endz = maxz; while (endz > 0 and (text[endz] & 0xC0) == 0x80) endz -= 1; return text[0..endz]; }
pub fn recoOf(aren: std.mem.Allocator, cfg: confz.Conf, chat: []const u8, who: []const u8, body: []const u8, ts: i64) !?Reco { const text = std.mem.trim(u8, cutUtf8(std.mem.trim(u8, body, " \t\r\n"), cfg.feed_text_maxz), " \t\r\n"); if (text.len == 0) return null; const ckey = try hexOf(aren, chat); const mkey = try hexOf(aren, try std.fmt.allocPrint(aren, "{s}|{s}|{d}|{s}", .{ chat, who, ts, body })); return .{ .kind = CF.kind, .id = mkey, .url = try std.fmt.allocPrint(aren, "{s}{s}/m/{s}", .{ CF.base, ckey, mkey }), .text = text, .src = chat, .auth = who, .role = CF.role, .posted = if (ts > 0 and ts < CF.secs) ts * 1000 else ts }; }
pub fn feedBuil(aren: std.mem.Allocator, sto: *data.Stor, cfg: confz.Conf) !Built { var outp: std.ArrayList(u8) = .empty; var marks: std.ArrayList(Mark) = .empty; var cntz: u32 = 0; var skpz: u32 = 0;
    for (cfg.feed_chat_list) |chat| { const mkey = try std.fmt.allocPrint(aren, "{s}{s}", .{ CF.metk, try hexOf(aren, chat) }); const lasz: i64 = if (try sto.metaGet(aren, mkey)) |txt| std.fmt.parseInt(i64, txt, 10) catch 0 else 0; var stm = try sto.dbzz.prep("SELECT id,who,body,ts FROM msgs WHERE chat=?1 AND id>?2 ORDER BY id LIMIT ?3;"); defer stm.fini(); try stm.bindText(1, chat); try stm.bindInt(2, lasz); try stm.bindInt(3, cfg.feed_item_maxz); var maxi = lasz; while (try stm.step()) { maxi = @max(maxi, stm.colInt(0)); const rec = (try recoOf(aren, cfg, chat, stm.colText(1), stm.colText(2), stm.colInt(3))) orelse { skpz += 1; continue; }; try outp.appendSlice(aren, try std.json.Stringify.valueAlloc(aren, rec, .{})); try outp.append(aren, '\n'); cntz += 1; } try marks.append(aren, .{ .key = mkey, .id = maxi }); }
    return .{ .body = outp.items, .cntz = cntz, .skpz = skpz, .marks = marks.items }; }
pub fn feedSave(aren: std.mem.Allocator, iozz: std.Io, sto: *data.Stor, built: Built, dirz: []const u8, nowm: i64) ![]const u8 { if (dirz.len == 0) return error.BadConfig; const path = try std.fmt.allocPrint(aren, "{s}{c}za-{d}.jsonl", .{ dirz, std.fs.path.sep, nowm }); try file.fileAtom(aren, iozz, path, built.body); for (built.marks) |mark| try sto.metaSet(mark.key, try std.fmt.allocPrint(aren, "{d}", .{mark.id})); return path; }
pub fn feedRun(ctx: *ctxz.Ctx) !u8 { if (ctx.cfg.feed_chat_list.len == 0) { try ctxz.emit(ctx, "no feed_chat_list set in the config\n"); return 3; } var sto = try ctxz.openStor(ctx); defer sto.close(); const built = try feedBuil(ctx.allo, &sto, ctx.cfg); const livz = ctx.args.mode == .live or ctx.args.mode == .force; if (built.cntz > 0 and livz) { const path = try feedSave(ctx.allo, ctx.iozz, &sto, built, ctx.feed, ctxz.nowMs(ctx)); try ctxz.emitf(ctx, "wrote {d} records to {s} ({d} skipped)\n", .{ built.cntz, path, built.skpz }); return 0; } try ctxz.emitf(ctx, "{d} records, {d} skipped{s}\n", .{ built.cntz, built.skpz, if (built.cntz > 0) " | add --live to write them for scra" else "" }); return if (built.cntz == 0) 3 else 0; }
